def csv2j(t): return list(csv.DictReader(io.StringIO(t)))
def b64e(t): return base64.b64encode(t.encode()).decode()
def b64d(t): return base64.b64decode(t.encode()).decode()
def uparse(u):
    p = urlparse(u)
    return (p.scheme, p.hostname, p.path)

if __name__ == "__main__":
    print(jfmt('{"b":2,"a":1}'))
    rows = csv2j("x,y\n1,2\n")
    assert rows == [{"x": "1", "y": "2"}]
    assert b64d(b64e("toolkit")) == "toolkit"
    assert uparse("https://example.com/docs?a=1") == ("https", "example.com", "/docs")
    print("OK: JSON/CSV/base64/URL tools all work in one toolkit")
